using FlaUI.Core; using FlaUI.UIA3; using Xunit; namespace MadagascarBrowser.UiTests; public sealed class ApplicationLaunchTests { [Fact] public void BrowserStartsAndExposesNamedTopLevelWindow() { var exe=Environment.GetEnvironmentVariable("MADAGASCARBROWSER_EXE"); Assert.False(string.IsNullOrWhiteSpace(exe)); Assert.True(File.Exists(exe),$"Missing executable: {exe}"); using var app=Application.Launch(exe!); using var automation=new UIA3Automation(); var window=app.GetMainWindow(automation,TimeSpan.FromSeconds(45)); Assert.NotNull(window); Assert.Contains("Madagascar Browser",window!.Title,StringComparison.OrdinalIgnoreCase); } }